mapper.sql:
FROM order_guest og
JOIN order_main om ON om.order_id = og.order_id
    AND om.is_deleted = 0
LEFT JOIN room r ON r.room_id = om.room_id
    AND r.camp_id = om.camp_id
    AND r.is_deleted = 0
    AND r.status = 1
LEFT JOIN channel_account ca ON ca.account_id = om.channel_id
    AND ca.camp_id = om.camp_id
WHERE om.camp_id = #{campId}

    AND om.poi_id = #{poiId}


    AND (
        om.order_no LIKE #{keyword}
        OR om.out_order_no LIKE #{keyword}
        OR og.guest_name LIKE #{keyword}
        OR og.guest_mobile LIKE #{keyword}
        OR r.room_name LIKE #{keyword}
        OR r.room_no LIKE #{keyword}
    )


    AND '5' = #{bizType}


    AND '0' = #{state}

mapper.select:
FROM order_guest og JOIN order_main om ON om.order_id = og.order_id AND om.is_deleted = 0 LEFT JOIN room r ON r.room_id = om.room_id AND r.camp_id = om.camp_id AND r.is_deleted = 0 AND r.status = 1 LEFT JOIN channel_account ca ON ca.account_id = om.channel_id AND ca.camp_id = om.camp_id WHERE om.camp_id = #{campId}
AND og.id = #{guestId}
AND om.order_no = #{orderNo}
ORDER BY om.updated_at DESC, og.id DESC LIMIT 1
